package com.estateflow.controller;
import com.estateflow.config.AppContext;import com.estateflow.exception.EstateFlowException;import com.estateflow.model.*;import com.estateflow.model.enums.MaintenancePriority;import com.estateflow.util.*;import javafx.fxml.FXML;import javafx.scene.control.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;
public final class WorkOrderListController extends AbstractController{
 private static final String ALL="All";@FXML private ComboBox<String> statusFilter,priorityFilter;@FXML private ComboBox<Property> propertyFilter;@FXML private ComboBox<Vendor> vendorFilter;@FXML private DatePicker fromDate,toDate;@FXML private CheckBox overdue;@FXML private TableView<WorkOrderRow> table;@FXML private Label notice;
 public WorkOrderListController(AppContext c,SceneNavigator n){super(c,n);}
 @FXML private void initialize(){statusFilter.getItems().setAll(ALL,WorkOrderStatus.DRAFT.name(),WorkOrderStatus.ASSIGNED.name(),WorkOrderStatus.IN_PROGRESS.name(),WorkOrderStatus.COMPLETED.name(),WorkOrderStatus.CANCELLED.name());statusFilter.setValue(ALL);priorityFilter.getItems().setAll(ALL);priorityFilter.getItems().addAll(Arrays.stream(MaintenancePriority.values()).map(Enum::name).toList());priorityFilter.setValue(ALL);propertyFilter.setConverter(new javafx.util.StringConverter<>(){public String toString(Property p){return p==null?ALL:p.getName()+" — "+p.getCity();}public Property fromString(String s){return null;}});vendorFilter.setConverter(new javafx.util.StringConverter<>(){public String toString(Vendor v){return v==null?ALL:v.name();}public Vendor fromString(String s){return null;}});UiTask.run(()->ctx.properties().findAll(),rows->propertyFilter.getItems().setAll(rows));UiTask.run(()->ctx.vendors().isAvailable()?ctx.vendors().search(null,true):List.<Vendor>of(),rows->vendorFilter.getItems().setAll(rows));TableUtil.column(table,"No.",60,WorkOrderRow::id);TableUtil.column(table,"Property",150,WorkOrderRow::propertyName);TableUtil.column(table,"Title",210,WorkOrderRow::title);TableUtil.column(table,"Vendor",150,WorkOrderRow::vendorName);TableUtil.column(table,"Request",80,r->r.maintenanceRequestId()==null?"":r.maintenanceRequestId());TableUtil.column(table,"Priority",85,r->r.priority().name());TableUtil.column(table,"Due",105,r->fmt.date(r.dueDate()));TableUtil.column(table,"Status",105,r->r.status().name());TableUtil.column(table,"Estimate",100,r->r.estimatedCost()==null?"":fmt.money(r.estimatedCost()));TableUtil.column(table,"Actual",100,r->r.actualCost()==null?"":fmt.money(r.actualCost()));TableUtil.column(table,"Expense",80,r->r.expenseId()==null?"":r.expenseId());reload();}
 @FXML private void reload(){String s=statusFilter.getValue(),p=priorityFilter.getValue();LocalDate from=fromDate.getValue(),to=toDate.getValue();boolean only=overdue.isSelected();Property selectedProperty=propertyFilter.getValue();Vendor selectedVendor=vendorFilter.getValue();Long propertyId=selectedProperty==null?null:selectedProperty.getPropertyId(),vendorId=selectedVendor==null?null:selectedVendor.id();WorkOrderStatus status=s==null||ALL.equals(s)?null:WorkOrderStatus.valueOf(s);MaintenancePriority priority=p==null||ALL.equals(p)?null:MaintenancePriority.valueOf(p);UiTask.run(()->ctx.workOrders().isAvailable()?new Loaded(true,ctx.workOrders().search(propertyId,vendorId,status,priority,from,to,only)):new Loaded(false,List.of()),loaded->{table.getItems().setAll(loaded.rows());notice.setText(loaded.ready()?"":"Work orders require the manual migration db/migrations/v1.7_vendors_work_orders.sql.");});}
 private record Loaded(boolean ready,List<WorkOrderRow> rows){}
 @FXML private void onAdd(){nav.<WorkOrderFormController>showDialog("work-order-form.fxml","New work order",c->c.init(null,this::reload));}
 @FXML private void onEdit(){WorkOrderRow r=selected();if(r!=null)UiTask.run(()->ctx.workOrders().get(r.id()),w->nav.<WorkOrderFormController>showDialog("work-order-form.fxml","Edit work order",c->c.init(w,this::reload)));}
 @FXML private void onAssign(){WorkOrderRow r=selected();if(r==null)return;UiTask.run(()->ctx.vendors().search(null,false),vendors->{List<Vendor> active=vendors.stream().filter(Vendor::active).toList();if(active.isEmpty()){AlertUtil.info("Work Orders","Add an active vendor first.");return;}List<String> choices=active.stream().map(v->v.id()+" — "+v.name()+" ("+v.category().name().replace('_',' ')+")").toList();ChoiceDialog<String> d=new ChoiceDialog<>(choices.getFirst(),choices);d.setTitle("Assign vendor");d.setHeaderText(null);d.setContentText("Assign work order #"+r.id()+" to:");d.showAndWait().ifPresent(x->{long id=Long.parseLong(x.substring(0,x.indexOf(' ')));UiTask.run(()->ctx.workOrders().assign(r.id(),id),w->{nav.toast("Vendor assigned");reload();});});});}
 @FXML private void onStatus(){WorkOrderRow r=selected();if(r==null)return;UiTask.run(()->ctx.workOrders().get(r.id()),w->{List<WorkOrderStatus> next=Arrays.stream(WorkOrderStatus.values()).filter(w.status()::canTransitionTo).toList();if(next.isEmpty()){AlertUtil.info("Work Orders","This work order is already closed.");return;}ChoiceDialog<WorkOrderStatus>d=new ChoiceDialog<>(next.getFirst(),next);d.setTitle("Work order status");d.setHeaderText(null);d.setContentText("Move #"+w.id()+" from "+w.status()+" to:");d.showAndWait().ifPresent(target->{if(target==WorkOrderStatus.COMPLETED)complete(w);else UiTask.run(()->ctx.workOrders().transition(w.id(),target,null,null),x->{nav.toast("Work order updated");reload();});});});}
 private void complete(WorkOrder w){TextInputDialog cost=new TextInputDialog(w.actualCost()==null?"":w.actualCost().toPlainString());cost.setTitle("Complete work order");cost.setHeaderText("Actual cost (optional)");cost.setContentText("Amount:");cost.showAndWait().ifPresent(value->{try{BigDecimal amount=InputParser.optionalMoney("actualCost","Actual cost",value);TextInputDialog note=new TextInputDialog();note.setTitle("Completion notes");note.setHeaderText(null);note.setContentText("Work completed:");note.showAndWait().ifPresent(n->{String notes=InputParser.optionalText(n);UiTask.run(()->ctx.workOrders().transition(w.id(),WorkOrderStatus.COMPLETED,amount,notes),x->{nav.toast("Work order completed");reload();});});}catch(EstateFlowException e){ErrorHandler.handle(e);}});}
 @FXML private void onExpense(){WorkOrderRow r=selected();if(r==null)return;if(r.status()!=WorkOrderStatus.COMPLETED){AlertUtil.info("Work Orders","Complete the work order before linking an expense.");return;}TextInputDialog d=new TextInputDialog();d.setTitle("Link expense");d.setHeaderText("Enter the existing expense number for this work order.\nCreate it in Expenses first; it must match the property, request and actual amount.");d.setContentText("Expense number:");d.showAndWait().ifPresent(value->{try{long id=Long.parseLong(value.trim());UiTask.run(()->ctx.workOrders().linkExpense(r.id(),id),w->{nav.toast("Expense linked; NOI uses the canonical expense record");reload();});}catch(NumberFormatException e){AlertUtil.info("Work Orders","Enter a valid expense number.");}});}
 private WorkOrderRow selected(){WorkOrderRow r=table.getSelectionModel().getSelectedItem();if(r==null)AlertUtil.info("Work Orders","Select a work order first.");return r;}
}
